import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;
void main()=>runApp(const PeoYameApp());
const green=Color(0xff245f49);
class PeoYameApp extends StatelessWidget{const PeoYameApp({super.key});@override Widget build(BuildContext c)=>MaterialApp(title:'Peo Yame',theme:ThemeData(colorScheme:ColorScheme.fromSeed(seedColor:green),useMaterial3:true),home:const Home());}
class Home extends StatefulWidget{const Home({super.key});@override State<Home> createState()=>_HomeState();}
class _HomeState extends State<Home>{int tab=0;String label='Demo data · simulated';Map<String,dynamic>? reading;final pages=['Overview','Trends','My Crops','Alerts','Settings'];
Future<void> refresh()async{try{final r=await http.get(Uri.parse('http://10.0.2.2:3000/api/status')).timeout(const Duration(seconds:3));if(r.statusCode==200){final d=jsonDecode(r.body);setState(()=>reading=d['reading']);}}catch(_){setState(()=>label='Offline · demo data');}}
@override void initState(){super.initState();refresh();}
Widget card(Widget w)=>Card(child:Padding(padding:const EdgeInsets.all(18),child:w));
@override Widget build(BuildContext c){final t=reading?['temperature']?.toString()??'18.2',h=reading?['humidity']?.toString()??'62';return Scaffold(appBar:AppBar(title:const Text('Peo Yame'),actions:[Padding(padding:const EdgeInsets.all(8),child:Chip(label:Text(label)))]),body:RefreshIndicator(onRefresh:refresh,child:ListView(padding:const EdgeInsets.all(16),children:[Text(pages[tab],style:Theme.of(c).textTheme.headlineMedium),if(tab==0)...[card(Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Chip(label:Text('In range')),const Text('Within configured limits. This does not mean the crop is safe.'),Text('Temperature  $t °C'),Text('Humidity  $h %'),const Text('Low · Target · High')])),card(const Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Rough storage estimate · Estimate',style:TextStyle(fontWeight:FontWeight.bold)),Text('About 3–5 weeks',style:TextStyle(fontSize:28)),Text('A rough guess from temperature and humidity only. It does not inspect your crop. Check your crops by hand every few days.')]))]else card(Text(tab==2?'No storage locations yet':tab==3?'Alert log. Text messages are not sent in this edition.':'Settings and account controls'))])),bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(i)=>setState(()=>tab=i),destinations:const[NavigationDestination(icon:Icon(Icons.dashboard_outlined),label:'Overview'),NavigationDestination(icon:Icon(Icons.show_chart),label:'Trends'),NavigationDestination(icon:Icon(Icons.grass),label:'My Crops'),NavigationDestination(icon:Icon(Icons.notifications_outlined),label:'Alerts'),NavigationDestination(icon:Icon(Icons.settings_outlined),label:'Settings')]));}}
